async function enterCloudContext(context){try{const remote=await window.CloudCompetition.loadCompetitionState();if(remote.payload?.config){state={...defaultState(),...remote.payload};localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}else if(context.profile.role==="admin"&&state.config){await window.CloudCompetition.saveCompetitionState(state)}if(context.profile.role==="admin"){if(state.config)await syncFinalSessionsIntoState();if(!state.config)showScreen("setupScreen");else showApp()}else{if(!state.config)throw new Error("لم يجهز المدير بيانات المسابقة بعد");$("#app").classList.add("hidden");showScreen("committeeApp");await renderCommitteeWorkspace()}}catch(error){toast(`تعذر فتح البيانات المشتركة: ${error.message}`);showScreen("cloudLoginScreen")}}
async function syncFinalSessionsIntoState(){committeeSessions=await window.CloudCompetition.listSessions();const committees=await window.CloudCompetition.listCommittees(),committeeById=new Map(committees.map(item=>[item.id,item.name]));let changed=false;committeeSessions.filter(session=>session.status==="final").forEach(session=>{const participant=state.participants.find(item=>item.id===session.participant_id);if(!participant)return;const assessment={...(session.assessment||{})};if(!assessment.committeeName&&committeeById.has(session.committee_id))assessment.committeeName=committeeById.get(session.committee_id);if(participant.score!==Number(session.score)||participant.assessment?.updatedAt!==assessment.updatedAt||participant.assessment?.committeeName!==assessment.committeeName){participant.score=Number(session.score);participant.gradedAt=session.finalized_at;participant.scoreSource="electronic";participant.assessment=assessment;changed=true}});if(changed)saveState()}
